private lemma eq_one_of_mul_eq_right {G : Type u} [CommGroup G] {a u : G}
    (h : a * u = u) : a = 1 :=
  mul_right_cancel (h.trans (one_mul u).symm)

private lemma mem_pointLattice_zero_iff {g : X.functionField} :
    g ∈ pointLattice K hx 0 ↔ Scheme.ord (X ↘ Spec (CommRingCat.of K)) hx g ≤ 1 := by
  rw [mem_pointLattice, ofAdd_zero, WithZero.coe_one]

private lemma not_nonempty_of_le_of_notMem {U W : X.Opens} (hWU : W ≤ U)
    (hη : genericPoint X ∉ U) : ¬ (W : Set X).Nonempty := fun h =>
  hη (hWU (Scheme.genericPoint_mem_of_nonempty h))

private theorem picClass_classDegFun_choose (L : X.CechPic) :
    CurveDivisor.picClass K (CurveDivisor.exists_picClass_eq K L).choose = L :=
  (CurveDivisor.exists_picClass_eq K L).choose_spec

def eval (U : T.left.affineOpens) : picEt C T →* PicEtAff C Γ(T.left, U.1) :=
  (Pi.evalMonoidHom (fun V : T.left.affineOpens => PicEtAff C Γ(T.left, V.1)) U).comp
    (picEtSubgroup C T).subtype

def picEtToAff : picEt C (overSpec k A) →* PicEtAff C A :=
  (PicEtAff.congr C (Over.overSpecΓTopAlgEquiv k A)).toMonoidHom.comp
    (picEt.eval C (overSpec k A) (overSpecTopAffine A))

private lemma preimage_overlap_eq :
    ov = π ⁻¹ᵁ Proj.basicOpen 𝒜 (X 0 * X 1) := by
  rw [← Scheme.Hom.preimage_inf, P1.chartOpen_inf K]

private lemma ratio_mul_cancel {G : Type u} [CommGroup G] (a b c : G) :
    a / b * (c / a) = c / b := by
  rw [div_mul_div_comm, mul_comm a c, mul_div_mul_right_eq_div]

private noncomputable def resLeft [Y.Over (Spec (.of k))] :
    Γ(Y, U₀) →ₗ[k] Γ(Y, U₀ ⊓ U₁) :=
  ((Y.moduleKSheaf k).obj.map (homOfLE (inf_le_left : U₀ ⊓ U₁ ≤ U₀)).op).hom

private noncomputable def resRight [Y.Over (Spec (.of k))] :
    Γ(Y, U₁) →ₗ[k] Γ(Y, U₀ ⊓ U₁) :=
  ((Y.moduleKSheaf k).obj.map (homOfLE (inf_le_right : U₀ ⊓ U₁ ≤ U₁)).op).hom

private lemma witness_div_global {G : Type u} [CommGroup G] {a b P Q c : G}
    (h : a * P = Q * b) : a / c * P = Q * (b / c) := by
  rw [div_mul_eq_mul_div, h, mul_div_assoc]

lemma OneCohomologyRelation.res {γ₁ γ₂ : OneCochain G U} {α : ZeroCochain G U}
    (h : OneCohomologyRelation γ₁ γ₂ α) (f : ∀ i, V i ⟶ U i) :
    OneCohomologyRelation (γ₁.res f) (γ₂.res f) (fun i ↦ G.map (f i).op (α i)) := by
  intro i j T a b
  simpa [← ConcreteCategory.comp_apply, ← Functor.map_comp, ← op_comp]
    using h i j (a ≫ f i) (b ≫ f j)

instance IsDescentCocycle.invertible_descended {u : (B ⊗[A] B)ˣ}
    (hu : IsDescentCocycle u) : Module.Invertible A hu.descended :=
  (DescentDatum.ofUnit u hu).invertible_descended

theorem trivialization_ext {t₁ t₂ : C ⊗[A] N ≃ₗ[C] C}
    (h : ∀ n : N, t₁ (1 ⊗ₜ n) = t₂ (1 ⊗ₜ n)) : t₁ = t₂ :=
  LinearEquiv.toLinearMap_injective (trivialization_hom_ext h)
